solution.solution.cpp:
#include <cstdint>
#include <map>
#include <optional>
#include <vector>

class Breakpoints
{
public:
    Breakpoints(std::vector<std::uint8_t>& code, std::uint64_t base) : code{ code }, base{ base } {}

    bool set(std::uint64_t address)
    {
        if (!inside(address) || saved.count(address)) return false;
        saved[address] = code[address - base];
        code[address - base] = 0xCC;
        return true;
    }

    bool remove(std::uint64_t address)
    {
        const auto it{ saved.find(address) };
        if (it == saved.end()) return false;
        code[address - base] = it->second;
        saved.erase(it);
        if (rearm == address) rearm.reset();
        return true;
    }

    bool isSet(std::uint64_t address) const { return saved.count(address) > 0; }

    std::vector<std::uint8_t> view() const
    {
        std::vector<std::uint8_t> shown{ code };
        for (const auto& [address, original] : saved) shown[address - base] = original;
        return shown;
    }

    std::optional<std::uint64_t> onBreakpoint(std::uint64_t& rip)
    {
        const std::uint64_t at{ rip - 1 };
        const auto it{ saved.find(at) };
        if (it == saved.end()) return std::nullopt;
        rip = at;
        code[at - base] = it->second;
        rearm = at;
        return at;
    }

    void onSingleStep()
    {
        if (rearm && saved.count(*rearm)) code[*rearm - base] = 0xCC;
        rearm.reset();
    }

private:
    std::vector<std::uint8_t>& code;
    std::uint64_t base;
    std::map<std::uint64_t, std::uint8_t> saved;
    std::optional<std::uint64_t> rearm;

    bool inside(std::uint64_t address) const { return address >= base && address - base < code.size(); }
};

unitTests:
using Bytes = std::vector<std::uint8_t>;
static Bytes program() { return { 0x48, 0x89, 0x5C, 0x24, 0x08, 0x57, 0x48, 0x83, 0xEC, 0x20, 0xCC, 0xC3 }; }

TEST("setting writes CC and view hides it") {
    Bytes code{ program() };
    Breakpoints bp{ code, 0x1000 };
    CHECK(bp.set(0x1005));
    CHECK_EQ(code[5], 0xCC);
    CHECK(bp.isSet(0x1005));
    CHECK(bp.view() == program());
    CHECK(!bp.set(0x1005));
    CHECK(!bp.set(0x2000));
    CHECK(!bp.set(0x0FFF));
}
TEST("removing restores the byte") {
    Bytes code{ program() };
    Breakpoints bp{ code, 0x1000 };
    bp.set(0x1000);
    CHECK(bp.remove(0x1000));
    CHECK(code == program());
    CHECK(!bp.remove(0x1000));
    CHECK(!bp.isSet(0x1000));
}
TEST("hitting, stepping and re-arming") {
    Bytes code{ program() };
    Breakpoints bp{ code, 0x1000 };
    bp.set(0x1006);
    std::uint64_t rip{ 0x1007 };
    const auto hit{ bp.onBreakpoint(rip) };
    CHECK(hit.has_value());
    CHECK_EQ(hit.value_or(0), 0x1006ull);
    CHECK_EQ(rip, 0x1006ull);
    CHECK_EQ(code[6], 0x48);
    bp.onSingleStep();
    CHECK_EQ(code[6], 0xCC);
    CHECK(bp.view() == program());
}
TEST("the program's own int3 is not ours") {
    Bytes code{ program() };
    Breakpoints bp{ code, 0x1000 };
    std::uint64_t rip{ 0x100B };
    CHECK(!bp.onBreakpoint(rip).has_value());
    CHECK_EQ(rip, 0x100Bull);
    CHECK_EQ(code[10], 0xCC);
}
TEST("removed while waiting to be re-armed") {
    Bytes code{ program() };
    Breakpoints bp{ code, 0x1000 };
    bp.set(0x1000);
    std::uint64_t rip{ 0x1001 };
    bp.onBreakpoint(rip);
    bp.remove(0x1000);
    bp.onSingleStep();
    CHECK(code == program());
}

